   </head>
   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div class="page-shell">
         <header class="hero">
           <h1>Computer Languages Quiz</h1>
           <p class="subtitle">
             Pick every answer that applies. Each question supports multiple selections.
           </p>
         </header>

         <form id="quiz-form" novalidate>
           <div id="quiz-root" class="quiz-grid" aria-describedby="quiz-status"></div>

           <div class="actions">
             <p id="quiz-status" class="status" aria-live="polite">
               <strong>Ready:</strong> choose your answers and submit when you're done.
             </p>
             <button type="submit">Submit quiz</button>
           </div>

           <div id="result" class="feedback" hidden aria-live="polite"></div>
         </form>
       </div>
     </main>

     <script>
       const quizData = [
         {
           id: "q1",
           prompt: "Which of these are programming languages?",
           helpText: "Select all that apply.",
           choices: [
             { id: "python", label: "Python", correct: true },
             { id: "html", label: "HTML", correct: false },
             { id: "javascript", label: "JavaScript", correct: true },
             { id: "css", label: "CSS", correct: false },
           ],
         },
         {
           id: "q2",
           prompt: "Which languages are commonly used for web development?",
           choices: [
             { id: "ruby", label: "Ruby", correct: true },
             { id: "go", label: "Go", correct: true },
             { id: "latex", label: "LaTeX", correct: false },
             { id: "sql", label: "SQL", correct: true },
           ],
         },
         {
           id: "q3",
           prompt: "Which of these are considered compiled languages in many workflows?",
           choices: [
             { id: "c", label: "C", correct: true },
             { id: "typescript", label: "TypeScript", correct: true },
             { id: "bash", label: "Bash", correct: false },
             { id: "php", label: "PHP", correct: true },
           ],
         },
       ];

       function createQuestion(question, index) {
         const helpId = question.helpText ? `${question.id}-help` : "";
         const wrapper = document.createElement("div");
         wrapper.className = "form-field";
         wrapper.dataset.questionId = question.id;

         const fieldset = document.createElement("fieldset");
         const legend = document.createElement("legend");
         legend.textContent = `${index + 1}. ${question.prompt}`;
         fieldset.appendChild(legend);

         if (question.helpText) {
           const help = document.createElement("p");
           help.className = "help-text";
           help.id = helpId;
           help.textContent = question.helpText;
           fieldset.appendChild(help);
         }

         const list = document.createElement("ul");
         list.className = "choices";

         question.choices.forEach((choice) => {
           const item = document.createElement("li");
           const label = document.createElement("label");
           label.className = "choice";

           const input = document.createElement("input");
           input.type = "checkbox";
           input.name = question.id;
           input.value = choice.id;
           input.dataset.correct = String(choice.correct);
           if (helpId) input.setAttribute("aria-describedby", helpId);

           const text = document.createElement("span");
           text.textContent = choice.label;

           label.appendChild(input);
           label.appendChild(text);
           item.appendChild(label);
           list.appendChild(item);
         });

         fieldset.appendChild(list);
         wrapper.appendChild(fieldset);
         return wrapper;
       }

       function renderQuiz() {
         const root = document.getElementById("quiz-root");
         quizData.forEach((question, index) => {
           root.appendChild(createQuestion(question, index));
         });
       }

       function getSelectedValues(questionId) {
         return Array.from(document.querySelectorAll(`input[name="${questionId}"]:checked`)).map(
           (input) => input.value,
         );
       }

       function getCorrectValues(question) {
         return question.choices.filter((choice) => choice.correct).map((choice) => choice.id);
       }

       function sameSet(left, right) {
         if (left.length !== right.length) return false;
         const sortedLeft = [...left].sort();
         const sortedRight = [...right].sort();
         return sortedLeft.every((value, index) => value === sortedRight[index]);
       }

       renderQuiz();

       const form = document.getElementById("quiz-form");
       const result = document.getElementById("result");
       const status = document.getElementById("quiz-status");

       form.addEventListener("submit", (event) => {
         event.preventDefault();

         let correctCount = 0;
         const questions = Array.from(document.querySelectorAll(".form-field"));

         questions.forEach((questionEl, index) => {
           questionEl.classList.remove("question-correct", "question-incorrect");
           const question = quizData[index];
           const selected = getSelectedValues(question.id);
           const expected = getCorrectValues(question);
           const isCorrect = sameSet(selected, expected);

           questionEl.classList.add(isCorrect ? "question-correct" : "question-incorrect");
           if (isCorrect) correctCount += 1;
         });

         result.hidden = false;
         result.innerHTML = `
           <p><strong class="score">${correctCount} of ${quizData.length} correct.</strong>
           ${correctCount === quizData.length ? "Nice work — all answers matched." : "Review the highlighted questions and try again if you'd like a better score."}</p>
         `;

         status.innerHTML = `<strong>Submitted:</strong> ${correctCount} of ${quizData.length} correct.`;
       });
     </script>
   </body>
 </html>

')
